ALTER TABLE "expiry_estimation_rules" ADD FOREIGN KEY ("storage_method_id") REFERENCES "storage_methods" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "purchases" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "purchases" ADD FOREIGN KEY ("purchase_source_id") REFERENCES "purchase_sources" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "purchase_items" ADD FOREIGN KEY ("purchase_id") REFERENCES "purchases" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "purchase_items" ADD FOREIGN KEY ("ingredient_catalog_id") REFERENCES "ingredient_catalog" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "purchase_items" ADD FOREIGN KEY ("unit_id") REFERENCES "units" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "inventory_items" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "inventory_items" ADD FOREIGN KEY ("ingredient_catalog_id") REFERENCES "ingredient_catalog" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "inventory_items" ADD FOREIGN KEY ("purchase_item_id") REFERENCES "purchase_items" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "inventory_items" ADD FOREIGN KEY ("status_id") REFERENCES "item_statuses" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "inventory_items" ADD FOREIGN KEY ("storage_method_id") REFERENCES "storage_methods" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "inventory_items" ADD FOREIGN KEY ("unit_id") REFERENCES "units" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "consumption_events" ADD FOREIGN KEY ("inventory_item_id") REFERENCES "inventory_items" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "consumption_events" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "consumption_events" ADD FOREIGN KEY ("event_source_id") REFERENCES "event_sources" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "notifications" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "notifications" ADD FOREIGN KEY ("inventory_item_id") REFERENCES "inventory_items" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "shopping_list_items" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

