-- V7: 이미지 업로드 메타데이터
CREATE TABLE uploaded_images (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id BIGINT NOT NULL REFERENCES users(id),
    purpose VARCHAR(20) NOT NULL CHECK (purpose IN ('RECEIPT', 'PROFILE', 'RECIPE')),
    bucket VARCHAR(63) NOT NULL,
    object_key VARCHAR(200) NOT NULL UNIQUE,
    content_type VARCHAR(30) NOT NULL CHECK (content_type IN ('image/jpeg', 'image/png')),
    size_bytes BIGINT NOT NULL CHECK (size_bytes BETWEEN 1 AND 5242880),
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    ready BOOLEAN NOT NULL DEFAULT FALSE
);
CREATE INDEX idx_uploaded_images_owner ON uploaded_images(user_id);
CREATE INDEX idx_uploaded_images_cleanup ON uploaded_images(ready, created_at);
COMMENT ON TABLE uploaded_images IS 'S3 이미지 메타데이터. ready=false는 업로드 중 또는 정리 재시도 대상';

ALTER TABLE purchases ADD FOREIGN KEY (image_id) REFERENCES uploaded_images(id);
ALTER TABLE purchase_items ADD FOREIGN KEY (storage_method_id) REFERENCES storage_methods(id);

-- V11: 프로필 이미지
ALTER TABLE users ADD COLUMN profile_image_id BIGINT REFERENCES uploaded_images(id);

-- V12: 식재료 이미지 등록
ALTER TABLE inventory_items ADD COLUMN image_id BIGINT REFERENCES uploaded_images(id);

ALTER TABLE uploaded_images DROP CONSTRAINT uploaded_images_purpose_check;
ALTER TABLE uploaded_images ADD CONSTRAINT uploaded_images_purpose_check
    CHECK (purpose IN ('RECEIPT', 'PROFILE', 'RECIPE', 'INGREDIENT'));

-- V13: 거래 기능 설계안(docs/vium.dbml #143) 테이블 적용. Java 코드는 아직 이 테이블을 쓰지 않는다.
-- 위치 컬럼은 PostGIS geography 대신 latitude/longitude(double precision)로 둔다.
-- 모든 시각 컬럼은 timestamp(시간대 없음)이며 DEFAULT now()를 쓰지 않는다.

ALTER TABLE "ingredient_catalog" ADD COLUMN "post_allowed" boolean NOT NULL DEFAULT true;

CREATE TABLE "credit_base_values" (
  "category_id" smallint NOT NULL,
  "unit_id" smallint NOT NULL,
  "base_value" numeric(8,3) NOT NULL,
  CONSTRAINT "credit_base_values_pkey" PRIMARY KEY ("category_id", "unit_id")
);

CREATE TABLE "posts" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "author_id" bigint NOT NULL,
  "inventory_item_id" bigint NOT NULL,
  "type" varchar(10) NOT NULL,
  "status" varchar(20) NOT NULL,
  "title" varchar(50) NOT NULL,
  "description" varchar(1000) NOT NULL DEFAULT '',
  "price" integer NOT NULL DEFAULT 0,
  "recommended_price" integer,
  "is_opened" boolean NOT NULL,
  "latitude" double precision NOT NULL,
  "longitude" double precision NOT NULL,
  "like_count" integer NOT NULL DEFAULT 0,
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL,
  "deleted_at" timestamp,
  CONSTRAINT "chk_posts_type" CHECK ("type" IN ('SHARE', 'SALE')),
  CONSTRAINT "chk_posts_status" CHECK ("status" IN ('OPEN', 'RESERVED', 'COMPLETED', 'EXPIRED')),
  CONSTRAINT "chk_posts_price_by_type" CHECK (("type" = 'SALE' AND "price" >= 1) OR ("type" = 'SHARE' AND "price" = 0)),
  CONSTRAINT "chk_posts_latitude" CHECK ("latitude" BETWEEN -90 AND 90),
  CONSTRAINT "chk_posts_longitude" CHECK ("longitude" BETWEEN -180 AND 180)
);

CREATE TABLE "post_images" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "post_id" bigint NOT NULL,
  "image_id" bigint UNIQUE NOT NULL,
  "sort_order" smallint NOT NULL
);

CREATE TABLE "post_likes" (
  "user_id" bigint NOT NULL,
  "post_id" bigint NOT NULL,
  "created_at" timestamp NOT NULL,
  CONSTRAINT "post_likes_pkey" PRIMARY KEY ("user_id", "post_id")
);

CREATE TABLE "trades" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "post_id" bigint NOT NULL,
  "buyer_id" bigint NOT NULL,
  "seller_id" bigint NOT NULL,
  "status" varchar(20) NOT NULL,
  "price" integer NOT NULL,
  "buyer_inventory_item_id" bigint UNIQUE,
  "canceled_by_id" bigint,
  "cancel_reason" varchar(200),
  "requested_at" timestamp NOT NULL,
  "accepted_at" timestamp,
  "auto_resolve_at" timestamp,
  "auto_complete_notified_at" timestamp,
  "completed_at" timestamp,
  "closed_at" timestamp,
  CONSTRAINT "chk_trades_status" CHECK ("status" IN ('REQUESTED', 'ACCEPTED', 'COMPLETED', 'REJECTED', 'CANCELED'))
);

CREATE TABLE "trade_reviews" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "trade_id" bigint NOT NULL,
  "writer_id" bigint NOT NULL,
  "target_user_id" bigint NOT NULL,
  "manner_score" smallint NOT NULL,
  "content" varchar(500),
  "created_at" timestamp NOT NULL,
  CONSTRAINT "chk_trade_reviews_manner_score" CHECK ("manner_score" BETWEEN 1 AND 5)
);

CREATE TABLE "credit_transactions" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" bigint NOT NULL,
  "type" varchar(30) NOT NULL,
  "amount" integer NOT NULL,
  "trade_id" bigint,
  "ai_waste_report_id" bigint,
  "reward_date" date,
  "provider_transaction_id" varchar(100) UNIQUE,
  "created_at" timestamp NOT NULL,
  CONSTRAINT "chk_credit_transactions_type" CHECK ("type" IN
    ('SIGNUP_REWARD', 'AD_REWARD', 'DAILY_REWARD', 'SAVING_BONUS', 'TRADE_HOLD', 'TRADE_REFUND', 'TRADE_INCOME', 'AI_REPORT'))
);

CREATE TABLE "chat_rooms" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "post_id" bigint NOT NULL,
  "buyer_id" bigint NOT NULL,
  "seller_id" bigint NOT NULL,
  "last_message_at" timestamp,
  "created_at" timestamp NOT NULL
);

CREATE TABLE "chat_participants" (
  "chat_room_id" bigint NOT NULL,
  "user_id" bigint NOT NULL,
  "last_read_message_id" bigint,
  "left_at" timestamp,
  CONSTRAINT "chat_participants_pkey" PRIMARY KEY ("chat_room_id", "user_id")
);

CREATE TABLE "chat_messages" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "chat_room_id" bigint NOT NULL,
  "sender_id" bigint,
  "type" varchar(10) NOT NULL,
  "content" varchar(1000),
  "image_id" bigint,
  "system_event" varchar(30),
  "created_at" timestamp NOT NULL,
  CONSTRAINT "chk_chat_messages_type" CHECK ("type" IN ('TEXT', 'IMAGE', 'SYSTEM'))
);

CREATE TABLE "user_blocks" (
  "blocker_id" bigint NOT NULL,
  "blocked_id" bigint NOT NULL,
  "created_at" timestamp NOT NULL,
  CONSTRAINT "user_blocks_pkey" PRIMARY KEY ("blocker_id", "blocked_id"),
  CONSTRAINT "chk_user_blocks_not_self" CHECK ("blocker_id" <> "blocked_id")
);

CREATE TABLE "user_reports" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "reporter_id" bigint NOT NULL,
  "target_type" varchar(10) NOT NULL,
  "target_user_id" bigint,
  "target_post_id" bigint,
  "reason" varchar(20) NOT NULL,
  "detail" varchar(500),
  "status" varchar(20) NOT NULL DEFAULT 'RECEIVED',
  "created_at" timestamp NOT NULL,
  CONSTRAINT "chk_user_reports_target_type" CHECK ("target_type" IN ('USER', 'POST')),
  CONSTRAINT "chk_user_reports_reason" CHECK ("reason" IN ('SPAM', 'FRAUD', 'PROHIBITED_ITEM', 'ABUSIVE', 'ETC')),
  CONSTRAINT "chk_user_reports_status" CHECK ("status" IN ('RECEIVED', 'REVIEWED')),
  CONSTRAINT "chk_user_reports_target_match" CHECK (
    ("target_type" = 'USER' AND "target_user_id" IS NOT NULL AND "target_post_id" IS NULL)
    OR ("target_type" = 'POST' AND "target_post_id" IS NOT NULL AND "target_user_id" IS NULL)
  )
);

CREATE TABLE "ai_waste_reports" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" bigint NOT NULL,
  "year_month" char(7) NOT NULL,
  "cost" integer NOT NULL,
  "summary" text NOT NULL,
  "insights" jsonb NOT NULL,
  "suggestions" jsonb NOT NULL,
  "created_at" timestamp NOT NULL
);

CREATE TABLE "user_push_tokens" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" bigint NOT NULL,
  "token" varchar(512) UNIQUE NOT NULL,
  "platform" varchar(10) NOT NULL,
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL,
  CONSTRAINT "chk_user_push_tokens_platform" CHECK ("platform" IN ('ANDROID', 'IOS'))
);

